New group is local to the machine that executed the command (**A3 2.08.149102**):

```sqf
player addAction ["Group Test (Dedicated Server)", {
    [[], {
        _test = createGroup [west, true];
        [str (local _test)] remoteExec ["hint", -2]; //tell all clients group locality; true
        missionNamespace setVariable ["Group_Reference", _test, true]; //broadcast group reference to all players
    }] remoteExec ["call", 2]; //create group on dedicated server only
    sleep 1;
    _newGroup = missionNamespace getVariable "Group_Reference"; //receive group reference from server
    systemChat format ["Group local to player: %1", local _newGroup]; //false
}];
```

examples.text:
Inheritance type checking:

```sqf
private _animalDeclaration = [
    ["#type", "IAnimal"],
    ["FurType", { "None" }] // default implementation
];

private _pigDeclaration = [
    ["#base", _animalDeclaration],
    ["#type", "Pig"],
    ["FurType", { "Bristles" }] // override the base class method
];

private _catDeclaration = [
    ["#base", _animalDeclaration],
    ["#type", "Cat"],
    ["FurType", { "Hair" }] // override the base class method
];

private _instance = createHashMapObject [selectRandom [_pigDeclaration, _catDeclaration]];

if ("IAnimal" in (_instance get "#type")) then // check if a object instance is or inherits from a specific type
{
    _instance call ["FurType"]; // now that we know it implements IAnimal, we know that "FurType" method will be present
};
```

code:
private _animalDeclaration = [
	["#type", "IAnimal"],
	["FurType", { "None" }] // default implementation
];

private _pigDeclaration = [
	["#base", _animalDeclaration],
	["#type", "Pig"],
	["FurType", { "Bristles" }] // override the base class method
];

private _catDeclaration = [
	["#base", _animalDeclaration],
	["#type", "Cat"],
	["FurType", { "Hair" }] // override the base class method
];

private _instance = createHashMapObject [selectRandom [_pigDeclaration, _catDeclaration]];

if ("IAnimal" in (_instance get "#type")) then // check if a object instance is or inherits from a specific type
{
	_instance call ["FurType"]; // now that we know it implements IAnimal, we know that "FurType" method will be present
};

