		apply { getUserInfo _x } select { _x select 7 }									// filter by HC
		apply { -(_x select 1) };														// get negative network ID

	if (_allNegativeHCs isNotEqualTo []) then
	{
		TO_ALL_PLAYERS = [TO_ALL_PLAYERS] + _allNegativeHCs;
	};

